import{_ as t,o as a,c as r,a6 as n}from"./chunks/framework.BHBQfcoO.js";const p=JSON.parse('{"title":"Main Engineering","description":"","frontmatter":{},"headers":[],"relativePath":"cards/main-engineering.md","filePath":"cards/main-engineering.md"}'),s={name:"cards/main-engineering.md"};function o(i,e,d,h,l,c){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="main-engineering" tabindex="-1">Main Engineering <a class="header-anchor" href="#main-engineering" aria-label="Permalink to &quot;Main Engineering&quot;">​</a></h1><p><strong>Main Engineering</strong> is a tab in every LCARdS card editor. It is a live window into the systems behind the card: its data sources, rules, theme tokens and templates, and where each of its values comes from.</p><hr><h2 id="opening-main-engineering" tabindex="-1">Opening Main Engineering <a class="header-anchor" href="#opening-main-engineering" aria-label="Permalink to &quot;Opening Main Engineering&quot;">​</a></h2><ol><li>Click the <strong>pencil (edit) icon</strong> on any LCARdS card</li><li>Select the <strong>Main Engineering</strong> tab in the editor panel</li></ol><hr><h2 id="panels" tabindex="-1">Panels <a class="header-anchor" href="#panels" aria-label="Permalink to &quot;Panels&quot;">​</a></h2><h3 id="data-sources" tabindex="-1">Data Sources <a class="header-anchor" href="#data-sources" aria-label="Permalink to &quot;Data Sources&quot;">​</a></h3><p>Manage the <a href="./../core/datasources/">Data Sources</a> attached to this card.</p><ul><li><strong>This card</strong>: the sources in this card&#39;s config. Add, edit or remove them; the editor previews the processors over the entity&#39;s recent history (see <a href="./../core/datasources/#in-the-card-editor">Data Sources: in the card editor</a>).</li><li><strong>All on this page</strong>: every source running on the dashboard, which cards use it and how it was created.</li><li><strong>Browse sources</strong>: a browser of every source on the page: its entity, processors and buffers, with live values.</li></ul><p>Create a source here, then use it in the card as <code>{ds:source_name}</code>.</p><hr><h3 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h3><p>The <a href="./../core/rules/">Rules Engine</a> from this card&#39;s point of view.</p><ul><li><strong>Rules targeting this card</strong>, and <strong>all rules on this page</strong>, with each rule&#39;s status, source card, target, conditions and changes.</li><li><strong>Add rule</strong> opens the rule editor; its <strong>Apply</strong> section is a YAML editor that completes this page&#39;s targets and each card&#39;s own settings.</li><li><strong>Edit as YAML</strong> (<code>{}</code>) edits one of this card&#39;s rules as a whole; other cards&#39; rules open read only.</li><li>A rule you have just changed or removed says <strong>refresh to apply</strong> until the page reloads: the engine loads each card&#39;s rules once.</li></ul><hr><h3 id="theme" tabindex="-1">Theme <a class="header-anchor" href="#theme" aria-label="Permalink to &quot;Theme&quot;">​</a></h3><p>The <a href="./../core/themes/">Theme</a> tokens this card uses, live: each token&#39;s value on the card (with a swatch for colours), the fields using it, and whether a theme override changes it. The copy button copies the <code>theme:</code> reference, ready to paste into card config.</p><p><strong>Open Theme Studio</strong> and <strong>Pack Explorer</strong> open those tabs of the <a href="./../configuration/#theme-studio">LCARdS Config Panel</a> in a new browser tab, so the editor stays open: browse every token and CSS variable there, tune alert modes and set overrides.</p><p>The tokens come from the card editor&#39;s preview, like <a href="#provenance">Provenance</a>.</p><hr><h3 id="provenance" tabindex="-1">Provenance <a class="header-anchor" href="#provenance" aria-label="Permalink to &quot;Provenance&quot;">​</a></h3><p>Where each of this card&#39;s values comes from, live.</p><p><strong>Open inspector</strong> lists every field the card knows about. Pick one to see its <strong>value now</strong> and <strong>how it got there</strong>, in order:</p><table tabindex="0"><thead><tr><th>Step</th><th>What it is</th></tr></thead><tbody><tr><td><strong>Card defaults, theme defaults</strong></td><td>Defaults registered for the card type</td></tr><tr><td><strong>Preset</strong> / <strong>Component</strong></td><td>The active <code>preset:</code> or <code>component:</code></td></tr><tr><td><strong>Your config</strong></td><td>The card&#39;s own YAML</td></tr><tr><td><strong>Applied by the card</strong></td><td>Values the card sets after reading the config: the <strong>state branch</strong> that applies now (<code>active</code>, <code>inactive</code>, a range key ...), a component preset&#39;s segments and text, a preset&#39;s default parameters, and <strong>built-in</strong> defaults (with the theme token they come from)</td></tr><tr><td><strong>Theme token</strong></td><td>For <code>theme:</code> values: each step to the colour on the card (an override and its scope, token references, the CSS variable, the final value)</td></tr><tr><td><strong>Template</strong></td><td>The template, its result and what it uses (entities, data sources, variables)</td></tr><tr><td><strong>Rule</strong></td><td>A rule changing the field right now, with its condition and the value it replaced</td></tr></tbody></table><p>Later steps win: a rule that applies overrides your config, which overrides the preset.</p><ul><li><strong>Show</strong> narrows the list: changed from defaults, set by rules now, templates, theme tokens, set by the card.</li><li><strong>Tokens</strong> lists every theme token the card uses, how each resolves, and the fields using it.</li><li><strong>Live</strong> follows the card as it changes (a rule starting or stopping, the entity changing state). Switch it off to hold the view; <strong>Refresh</strong> catches up.</li></ul><p>Provenance comes from the card editor&#39;s preview, the card rendered from the config you are editing. Layout cards and the alert overlay don&#39;t record it.</p><hr><h3 id="templates" tabindex="-1">Templates <a class="header-anchor" href="#templates" aria-label="Permalink to &quot;Templates&quot;">​</a></h3><p>Every template in this card&#39;s config, one row per field, with its live result (Jinja2 included) and any syntax mistake. <strong>Open in sandbox</strong> loads a field into the template sandbox, which completes entity attributes, data sources, theme tokens and variables, shows what the template used, and can save it back to the field. See <a href="./../core/templates/">Templates</a>.</p><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../core/datasources/">Data Sources</a>: subscription config and processing pipeline reference</li><li><a href="./../core/rules/">Rules Engine</a>: rule conditions, targets, and style patches</li><li><a href="./../core/themes/">Themes</a>: token namespaces and colour palette</li><li><a href="./../core/templates/">Templates</a>: template syntax</li><li><a href="./../core/presets.html">Presets</a>: how presets compose with card config</li></ul>',34)])])}const u=t(s,[["render",o]]);export{p as __pageData,u as default};
